import * as T from './vendor/three.module.js';
export class MemoryParticles {
  constructor(container, orbit, onSelect) {
    this.container=container; this.orbit=orbit; this.onSelect=onSelect; this.active=false;
    this.spread=0; this.targetSpread=0; this.zoom=1; this.targetZoom=1; this.rotation=0; this.targetRotation=0; this.shape='heart'; this.palette='rose'; this.reduced=false;
    this.renderer=new T.WebGLRenderer({antialias:true,alpha:true}); this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.6)); this.renderer.setSize(innerWidth,innerHeight); this.renderer.setClearColor(0,0); container.append(this.renderer.domElement);
    this.scene=new T.Scene(); this.camera=new T.PerspectiveCamera(43,innerWidth/innerHeight,.1,70); this.camera.position.set(0,0,9);
    this.count=innerWidth<650?5000:8500; this.positions=new Float32Array(this.count*3); this.targets=new Float32Array(this.count*3); this.cloud=new Float32Array(this.count*3); this.colors=new Float32Array(this.count*3); this.sizes=new Float32Array(this.count);
    this.seeds=Array.from({length:this.count},()=>[Math.random(),Math.random(),Math.random(),Math.random()]);
    for(let i=0;i<this.count;i++){const [a,b,c,d]=this.seeds[i];const theta=a*Math.PI*2,z=b*2-1,r=2.2+Math.cbrt(c)*3.5;this.cloud.set([Math.sqrt(1-z*z)*Math.cos(theta)*r,z*r*.7,Math.sqrt(1-z*z)*Math.sin(theta)*r*.55],i*3);this.sizes[i]=d>.965?15+d*7:2.2+d*4.4;}
    this.geometry=new T.BufferGeometry();this.geometry.setAttribute('position',new T.BufferAttribute(this.positions,3));this.geometry.setAttribute('color',new T.BufferAttribute(this.colors,3));this.geometry.setAttribute('size',new T.BufferAttribute(this.sizes,1));
    this.material=new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,vertexColors:true,uniforms:{pixelRatio:{value:Math.min(devicePixelRatio,1.6)},time:{value:0}},vertexShader:'attribute float size;varying vec3 vColor;uniform float pixelRatio;uniform float time;void main(){vColor=color;vec4 mv=modelViewMatrix*vec4(position,1.);gl_Position=projectionMatrix*mv;gl_PointSize=min(38.,size*pixelRatio*10./-mv.z)*(0.88+0.12*sin(time*1.5+position.x*6.+position.y*3.));}',fragmentShader:'varying vec3 vColor;void main(){vec2 p=gl_PointCoord-.5;float d=length(p);if(d>.5)discard;float a=exp(-d*d*22.)*.95;float core=exp(-d*d*140.);gl_FragColor=vec4(vColor*1.25+vec3(core*.6),a);}' });
    this.points=new T.Points(this.geometry,this.material);this.points.frustumCulled=false;this.scene.add(this.points);this.setShape('heart');this.positions.set(this.targets);this.setPalette('rose');this.cards=[];this.bindPointer();window.addEventListener('resize',()=>this.resize());
  }
  setShape(shape){if(!['heart','saturn','sphere'].includes(shape))return;this.shape=shape;for(let i=0;i<this.count;i++){const [a,b,c]=this.seeds[i],theta=a*Math.PI*2;let x,y,z;if(shape==='heart'){const r=Math.sqrt(b);x=16*Math.pow(Math.sin(theta),3)*r/10;y=(13*Math.cos(theta)-5*Math.cos(2*theta)-2*Math.cos(3*theta)-Math.cos(4*theta))*r/10+.15;z=(c-.5)*.9*Math.sqrt(1-r*.75);}else if(shape==='saturn'){if(i%3){const phi=Math.acos(2*b-1),r=1.13; x=r*Math.sin(phi)*Math.cos(theta);y=r*Math.cos(phi);z=r*Math.sin(phi)*Math.sin(theta);}else{const r=1.7+b*.8;x=r*Math.cos(theta);y=r*Math.sin(theta)*.32;z=r*Math.sin(theta)*.65;}}else{const phi=Math.acos(2*b-1),r=1.5*(.85+c*.15);x=r*Math.sin(phi)*Math.cos(theta);y=r*Math.cos(phi);z=r*Math.sin(phi)*Math.sin(theta);}this.targets.set([x,y,z],i*3);}}
  setPalette(name){this.palette=name;const choices=({rose:['#f485a8','#e76492','#ffbfbd','#dd9b64'],gold:['#f6d08e','#b48a3b','#fff2c3','#d3a85b'],blue:['#77d6e7','#4364ba','#c1a6ff','#bdfff1']})[name];if(!choices)return;for(let i=0;i<this.count;i++){const col=new T.Color(choices[i%choices.length]);this.colors.set([col.r,col.g,col.b],i*3);}this.geometry.attributes.color.needsUpdate=true;}
  setSpread(value){this.targetSpread=Math.max(0,Math.min(1,value));}
  setZoom(value){this.targetZoom=Math.max(.65,Math.min(1.65,value));}
  setCards(items){this.orbit.replaceChildren();this.cards=items.map((item,index)=>{const button=document.createElement('button');button.className='orbit-card'+(item.type==='audio'?' voice-card':item.type==='note'?' note-card':'');button.setAttribute('aria-label','打开回忆：'+item.title);if(item.type==='photo'){const image=document.createElement('img');image.src=item.src;image.alt=item.title;button.append(image);}else{const glyph=document.createElement('b');glyph.className='voice-mark';glyph.textContent=item.type==='audio'?'≋':'✧';button.append(glyph);}const title=document.createElement('span');title.textContent=item.title;button.append(title);if(item.type!=='photo'){const small=document.createElement('small');small.textContent=item.type==='audio'?(item.src?'一段专属的声音':'示例 · 语音朗读'):'有句话，想对你说';button.append(small);}button.onclick=()=>this.onSelect(index);this.orbit.append(button);return{element:button,index,point:new T.Vector3()};});}
  resize(){this.camera.aspect=innerWidth/innerHeight;this.camera.fov=innerWidth<650?51:43;this.camera.updateProjectionMatrix();this.renderer.setSize(innerWidth,innerHeight);}
  bindPointer(){let oldX=0,previousSpan=0;const pointers=new Map(),canvas=this.renderer.domElement;canvas.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});oldX=e.clientX;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],span=Math.hypot(a.x-b.x,a.y-b.y);if(previousSpan)this.setZoom(this.targetZoom*span/previousSpan);previousSpan=span;}else{this.targetRotation+=(e.clientX-oldX)*.005;oldX=e.clientX;}});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{pointers.delete(e.pointerId);previousSpan=0;});canvas.addEventListener('wheel',e=>{e.preventDefault();this.setZoom(this.targetZoom-e.deltaY*.0008);},{passive:false});}
  update(dt,time){if(!this.active)return;const k=1-Math.exp(-dt*(this.reduced?20:3.1));this.spread+=(this.targetSpread-this.spread)*k;this.zoom+=(this.targetZoom-this.zoom)*k;this.rotation+=(this.targetRotation-this.rotation)*k;const p=this.positions,shape=this.targets,cloud=this.cloud;for(let i=0;i<this.count;i++){const a=i*3;for(let j=0;j<3;j++){const value=shape[a+j]*(1-this.spread)+cloud[a+j]*this.spread;p[a+j]+=(value-p[a+j])*k;}}
    this.geometry.attributes.position.needsUpdate=true;this.points.rotation.y=this.rotation+(this.reduced?0:Math.sin(time*.18)*.14);this.points.rotation.z=this.reduced?0:Math.sin(time*.12)*.025;this.points.scale.setScalar(this.zoom*(1+(this.reduced?0:Math.sin(time*1.4)*.025)));this.points.position.x=innerWidth>700?.45:0;this.points.position.y=innerWidth>600?-.1:.1;this.material.uniforms.time.value=time;this.camera.updateMatrixWorld();this.renderer.render(this.scene,this.camera);
    const count=this.cards.length,mobile=innerWidth<650,portrait=mobile&&innerHeight>innerWidth,compact=innerHeight<520;for(const card of this.cards){const angle=card.index/count*Math.PI*2+this.rotation*.18+(this.reduced?0:Math.sin(time*.13)*.05);const radius=(1.3+this.spread*1.6)*this.zoom;card.point.set(Math.cos(angle)*radius+(mobile?0:.5),Math.sin(angle)*radius*.62+(mobile?.1:0),Math.sin(angle*1.7)*.75);const p=card.point.clone().project(this.camera),scale=Math.max(.65,Math.min(1.2,1+card.point.z*.09));const x=(p.x*.5+.5)*innerWidth,y=(-p.y*.5+.5)*innerHeight;const left=portrait?62:compact?190:225,right=innerWidth-(portrait?62:compact?110:85),top=portrait?235:compact?165:285,bottom=innerHeight-(portrait?270:compact?110:180);card.element.style.transform=`translate(${Math.max(left,Math.min(right,x))}px,${Math.max(Math.min(top,bottom),Math.min(bottom,y))}px) translate(-50%,-50%) scale(${scale*(.75+this.spread*.25)}) rotate(${Math.sin(angle)*2}deg)`;const visible=this.spread>.23;card.element.style.opacity=visible?String(Math.min(1,(this.spread-.23)*2.7)):'0';card.element.style.pointerEvents=visible?'auto':'none';card.element.tabIndex=visible?0:-1;card.element.setAttribute('aria-hidden',String(!visible));card.element.style.zIndex=String(Math.round((card.point.z+2)*10));}
  }
}
